#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!(cin >> s)) return 0;

    int suit_idx[256];
    suit_idx['C'] = 0;
    suit_idx['E'] = 1;
    suit_idx['U'] = 2;
    suit_idx['P'] = 3;

    bool seen[4][14] = {};
    bool has_duplicate[4] = {};
    int count[4] = {};

    for (size_t i = 0; i < s.length(); i += 3) {
        int val = (s[i] - '0') * 10 + (s[i + 1] - '0');
        char suit_char = s[i + 2];
        int suit = suit_idx[(unsigned char)suit_char];

        if (seen[suit][val]) {
            has_duplicate[suit] = true;
        } else {
            seen[suit][val] = true;
            count[suit]++;
        }
    }

    for (int i = 0; i < 4; ++i) {
        if (has_duplicate[i]) {
            cout << "erro\n";
        } else {
            cout << 13 - count[i] << "\n";
        }
    }

    return 0;
}
